define(["jquery","core/ajax","core/notification","core/str","mod_videoprogress/player","mod_videoprogress/content"],function($,Ajax,Notification,Str,Player,VideoContent){const HEARTBEAT_SECONDS=10;class Tracker{constructor(root,config){this.root=root;this.config=config;this.sequence=0;this.sessionkey=this.randomKey();this.playing=false;this.pendingStart=null;this.pendingEnd=null;this.lastTime=Number(config.lastposition||0);this.segments=Array.isArray(config.segments)?config.segments:[];this.queueKey="mod_videoprogress_queue_"+config.cmid;this.memoryQueue=[];this.storageAvailable=true;this.sending=false}initialise(){return Player.create(this.root,this.config.player).then(player=>{this.player=player;this.bindEvents();this.content=VideoContent.initialise(this.root,this.config.content||{},this.player);this.applyResume();this.drainQueue();this.timer=window.setInterval(()=>{if(this.playing){this.flush("playing")}},HEARTBEAT_SECONDS*1e3);return this}).catch(error=>{this.showMessage("invalidplayer");throw error})}bindEvents(){this.player.onPlay(()=>{this.playing=true;this.lastTime=this.player.getCurrentTime();this.pendingStart=this.lastTime;this.pendingEnd=this.lastTime});this.player.onTimeUpdate(current=>this.timeUpdate(Number(current)));this.player.onPause(()=>{this.playing=false;this.flush("paused")});this.player.onEnded(()=>{this.playing=false;this.flush("ended")});this.player.onSeek((current,previous)=>this.seek(Number(current),Number(previous||this.lastTime)));document.addEventListener("visibilitychange",()=>{if(document.hidden){this.flush("hidden")}else{this.drainQueue()}});window.addEventListener("pagehide",()=>this.flush("closed"));window.addEventListener("online",()=>this.drainQueue())}timeUpdate(current){if(!this.playing||!Number.isFinite(current)){this.lastTime=current;return}const rate=Math.max(.25,this.player.getPlaybackRate());const delta=current-this.lastTime;if(delta>=0&&delta<=Math.max(3,rate*3)){if(this.pendingStart===null){this.pendingStart=this.lastTime}this.pendingEnd=current}this.lastTime=current}seek(current,previous){if(!this.config.allowseek&&Math.abs(current-previous)>.25&&!this.isWatched(current)){this.player.seek(previous);this.showMessage("seekblocked");return}this.flush("seeking");this.lastTime=current;this.pendingStart=this.playing?current:null;this.pendingEnd=this.pendingStart}flush(state){if(!this.player){return}const current=this.player.getCurrentTime();const start=this.pendingStart===null?current:this.pendingStart;const end=this.pendingEnd===null?start:this.pendingEnd;this.pendingStart=this.playing?current:null;this.pendingEnd=this.pendingStart;const payload={cmid:Number(this.config.cmid),currentposition:Number(current||0),duration:Number(this.player.getDuration()||0),playbackrate:Number(this.player.getPlaybackRate()||1),segmentstart:Number(start||0),segmentend:Number(Math.max(start,end)||0),sequence:++this.sequence,sessionkey:this.sessionkey,clienttime:Math.floor(Date.now()/1e3),playerstate:state};if(payload.duration<=0){return}this.enqueue(payload);this.drainQueue()}enqueue(payload){const queue=this.readQueue();queue.push(payload);this.writeQueue(queue)}drainQueue(){if(this.sending||!navigator.onLine){return}const queue=this.readQueue();if(!queue.length){return}const pending=queue[0];this.sending=true;Ajax.call([{methodname:"mod_videoprogress_update_progress",args:pending}])[0].then(response=>{const currentQueue=this.readQueue();const acknowledged=currentQueue.findIndex(item=>item.sessionkey===pending.sessionkey&&Number(item.sequence)===Number(pending.sequence));if(acknowledged!==-1){currentQueue.splice(acknowledged,1)}this.writeQueue(currentQueue);this.applyResponse(response);this.sending=false;this.drainQueue()}).catch(()=>{this.sending=false;this.showMessage("pendingupdates")})}applyResponse(response){try{this.segments=JSON.parse(response.segments||"[]")}catch(error){this.segments=[]}if(response.reason==="seekblocked"||response.reason==="interactionrequired"){this.player.seek(response.correctposition);this.showMessage(response.reason)}const percentage=Math.round(Number(response.percent||0));const watched=Number(response.uniquewatched||0);const percent=this.root.querySelector('[data-region="percent"]');const bar=this.root.querySelector('[data-region="progress-bar"]');const progressbar=bar?bar.parentElement:null;const progressText=this.root.querySelector('[data-region="progress-text"]');const watchedDuration=this.root.querySelector('[data-region="watched-duration"]');if(percent){percent.textContent=percentage+"%"}if(bar){bar.style.width=Number(response.percent||0)+"%"}if(progressbar){progressbar.setAttribute("aria-valuenow",percentage)}if(watched>0){if(progressText){progressText.classList.remove("d-none");Str.get_string("watchedpercent","videoprogress",percentage).then(message=>{progressText.textContent=message})}if(watchedDuration){const duration=this.player?Number(this.player.getDuration()||0):0;watchedDuration.classList.remove("d-none");Str.get_string("watchedofduration","videoprogress",{uniquewatched:this.formatTime(watched),duration:this.formatTime(duration)}).then(message=>{watchedDuration.textContent=message})}}if(response.completed){this.showMessage("activitycompleted","success")}}applyResume(){const position=Number(this.config.lastposition||0);if(position<=1||Number(this.config.resumeplayback)===0){return}if(Number(this.config.resumeplayback)===1){this.player.seek(position);return}Promise.all([Str.get_string("resumequestion","videoprogress",this.formatTime(position)),Str.get_string("resumeyes","videoprogress"),Str.get_string("resumeno","videoprogress")]).then(strings=>Notification.confirm("",strings[0],strings[1],strings[2],()=>this.player.seek(position),()=>this.player.seek(0)))}isWatched(position){return this.segments.some(segment=>position>=Number(segment[0])-.25&&position<=Number(segment[1])+.25)}readQueue(){if(!this.storageAvailable){return this.memoryQueue.slice()}try{const queue=JSON.parse(window.localStorage.getItem(this.queueKey)||"[]");return Array.isArray(queue)&&queue.length?queue:this.memoryQueue.slice()}catch(error){this.storageAvailable=false;return this.memoryQueue.slice()}}writeQueue(queue){this.memoryQueue=queue.slice();try{window.localStorage.setItem(this.queueKey,JSON.stringify(queue));this.memoryQueue=[];this.storageAvailable=true}catch(error){this.storageAvailable=false}}showMessage(key,type){Str.get_string(key,"videoprogress").then(message=>{const element=this.root.querySelector('[data-region="tracking-message"]');if(!element){return}element.textContent=message;element.className="alert alert-"+(type||"warning");window.setTimeout(()=>element.classList.add("d-none"),5e3)})}randomKey(){const bytes=new Uint8Array(24);window.crypto.getRandomValues(bytes);return Array.from(bytes,byte=>byte.toString(16).padStart(2,"0")).join("")}formatTime(seconds){const value=Math.max(0,Math.round(seconds));const hours=Math.floor(value/3600);const minutes=Math.floor(value%3600/60);const remaining=value%60;return(hours?String(hours).padStart(2,"0")+":":"")+String(minutes).padStart(2,"0")+":"+String(remaining).padStart(2,"0")}}const init=()=>{document.querySelectorAll('[data-region="videoprogress"]').forEach(root=>{try{const config=JSON.parse(root.dataset.config||"{}");new Tracker(root,config).initialise()}catch(error){Notification.exception(error)}})};return{init:init}});